/*! htmx - high power tools for HTML (minimal offline build) */
(function(){
  var htmx = {version:"2.0.4"};
  var VERBS = ['get','post','put','delete','patch'];
  var defined = function(v){return v!==undefined&&v!==null};
  function parseInterval(s){if(!s)return 0;if(s.indexOf('ms')>-1)return parseInt(s);if(s.indexOf('s')>-1)return parseInt(s)*1000;return 1000}
  function getTarget(elt){var t=elt.getAttribute('hx-target');if(t){if(t==='this')return elt;if(t==='closest')return elt.parentElement;return document.querySelector(t)}return elt}
  function getSwapStyle(elt){return elt.getAttribute('hx-swap')||'innerHTML'}
  function getTrigger(elt){return elt.getAttribute('hx-trigger')||'default'}
  function doSwap(target,content,swapStyle){
    if(swapStyle==='outerHTML'){target.outerHTML=content}
    else if(swapStyle==='beforebegin'){target.insertAdjacentHTML('beforebegin',content)}
    else if(swapStyle==='afterbegin'){target.insertAdjacentHTML('afterbegin',content)}
    else if(swapStyle==='beforeend'){target.insertAdjacentHTML('beforeend',content)}
    else if(swapStyle==='afterend'){target.insertAdjacentHTML('afterend',content)}
    else if(swapStyle==='none'){}
    else{target.innerHTML=content}
    processNode(target);
  }
  function issueRequest(elt,verb,url){
    var target=getTarget(elt);
    var swap=getSwapStyle(elt);
    var vals='';
    if(verb!=='get'){
      var form=elt.closest('form');
      if(form){vals=new URLSearchParams(new FormData(form)).toString()}
      else if(elt.tagName==='FORM'){vals=new URLSearchParams(new FormData(elt)).toString()}
    }
    var xhr=new XMLHttpRequest();
    if(verb==='get'&&vals){url+=(url.indexOf('?')>-1?'&':'?')+vals;vals=null}
    xhr.open(verb.toUpperCase(),url,true);
    xhr.setRequestHeader('HX-Request','true');
    xhr.setRequestHeader('HX-Current-URL',window.location.href);
    if(verb!=='get'){xhr.setRequestHeader('Content-Type','application/x-www-form-urlencoded')}
    xhr.onload=function(){
      if(xhr.status>=200&&xhr.status<300){
        doSwap(target,xhr.responseText,swap);
        if(elt.getAttribute('hx-push-url')==='true'){history.pushState({},null,url)}
      }
    };
    xhr.send(vals);
  }
  function processNode(elt){
    if(!elt||!elt.querySelectorAll)return;
    var all=elt.querySelectorAll('[hx-get],[hx-post],[hx-put],[hx-delete],[hx-patch]');
    for(var i=0;i<all.length;i++){processElement(all[i])}
  }
  function processElement(elt){
    if(elt._htmxProcessed)return;
    elt._htmxProcessed=true;
    VERBS.forEach(function(verb){
      var url=elt.getAttribute('hx-'+verb);
      if(!url)return;
      var trigger=getTrigger(elt);
      var events=[];
      var polling=null;
      if(trigger.indexOf('every ')===0){
        var interval=parseInterval(trigger.replace('every ','').trim());
        polling=setInterval(function(){issueRequest(elt,verb,url)},interval);
        return;
      }
      var parts=trigger.split(',');
      parts.forEach(function(part){
        part=part.trim();
        if(part==='default'){
          if(elt.tagName==='FORM'){events.push('submit')}
          else if(elt.tagName==='INPUT'||elt.tagName==='SELECT'||elt.tagName==='TEXTAREA'){events.push('change')}
          else{events.push('click')}
        }else{
          var evName=part.split(' ')[0];
          events.push(evName);
        }
      });
      events.forEach(function(ev){
        elt.addEventListener(ev,function(e){
          if(elt.tagName==='FORM'||elt.tagName==='A'||(elt.tagName==='BUTTON'&&elt.type==='submit')){e.preventDefault()}
          issueRequest(elt,verb,url);
        });
      });
    });
  }
  document.addEventListener('DOMContentLoaded',function(){processNode(document.body)});
  var observer=new MutationObserver(function(mutations){
    mutations.forEach(function(m){
      m.addedNodes.forEach(function(n){if(n.nodeType===1)processNode(n)});
    });
  });
  observer.observe(document.body||document.documentElement,{childList:true,subtree:true});
  window.htmx=htmx;
})();
